// Intercepta la tecla K cuando tenemos puesta la herramienta suelo_flotante_recortes
// SOLAMENTE cuando se está en modo de juego activo con el puntero capturado (pointer lock).
// Si el editor de código, selector o modales están abiertos, o el foco está en un input/textarea, no intercepta nada.
if (window._kSueloFlotanteHandler) {
  window.removeEventListener('keydown', window._kSueloFlotanteHandler, true);
}
window._kSueloFlotanteHandler = (e) => {
  if (!mc.active || mc.tool !== 'suelo_flotante_recortes') return;
  // Solo actúa si el puntero está capturado en el juego
  if (document.pointerLockElement !== mc.canvas) return;
  // Comprueba que no haya modales, paneles o editores de texto abiertos
  if (typeof snipTapaElMundo === 'function' && snipTapaElMundo()) return;
  if ($('#snip-modal') && !$('#snip-modal').hidden) return;
  if ($('#mc-picker') && !$('#mc-picker').hidden) return;
  if ($('#mc-note') && !$('#mc-note').hidden) return;
  if ($('#ag-modal') && !$('#ag-modal').hidden) return;
  if (typeof mcRecortesAbierta === 'function' && mcRecortesAbierta()) return;
  if (e.target && e.target.matches && e.target.matches('input,select,textarea')) return;

  const k = e.key.toLowerCase();
  if ((k === 'k' || (e.altKey && e.code === 'KeyK')) && !e.ctrlKey && !e.metaKey) {
    if (e.altKey) return; // Alt+K sigue abriendo la galería
    // Conmuta la selección a K
    mc._sueloUsaK = !mc._sueloUsaK;
    if (mc.pasteActive && typeof mcPasteCancel === 'function') mcPasteCancel();
    const lista = typeof mcRecortesCarga === 'function' ? mcRecortesCarga() : (mc.recortes || []);
    const r = lista[mc.recorteSel | 0];
    if (mc._sueloUsaK) {
      toast('Ranura K seleccionada (' + (r ? r.nombre : 'sin recortes') + ') · Clic dcho pone el recorte bajo tus pies');
    } else {
      toast('Ranuras 1-9 seleccionadas · Clic dcho pone baldosa 3x3');
    }
    e.preventDefault();
    e.stopImmediatePropagation();
  }
  // Si pulsa 1-9, desactivamos el modo K para volver a la ranura de bloques
  if (/^[1-9]$/.test(e.key) && !e.altKey && !e.ctrlKey && !e.metaKey) {
    mc._sueloUsaK = false;
  }
};
window.addEventListener('keydown', window._kSueloFlotanteHandler, true);

game.herramientas.define('suelo_flotante_recortes', {
  // ── QUÉ SE LLEVA EN LA MANO ────────────────────────────────────────────────────────────────────
  dibujo: 'hab:caballito-de-mar-hd',
  nombre: 'suelo flotante (K)',
  mira: '⊙',
  ayuda: 'suelo_flotante · clic izq: romper · clic dcho: baldosa (1-9) o recorte bajo pies (K)',

  // ── POSTURA EN LA MANO ─────────────────────────────────────────────────────────────────────────
  pos: [0.85, -0.55, 0],
  rot: [-6, -80, -18],
  escala: 0.75,
  alcance: 4,

  // ── EL GESTO DEL CLIC ──────────────────────────────────────────────────────────────────────────
  gesto: { dur: 0.50, windupP: 0.12, strikeP: 0.042, windupRot: -0.55, chopRot: 0.60, lift: 0.016, drop: 0.05, reach: -0.0155 },
  gestoBotones: [0, 2],

  anima(e){
    const quieta = (e.disparo < 0) ? 1 : 0;
    return {
      pos: [0, Math.sin(e.t * 1.4) * 0.012 * quieta, 0],
      rot: [0, 0, Math.sin(e.t * 0.9) * 2.5 * quieta]
    };
  },

  // ── BOTÓN IZQUIERDO: Romper bloque apuntado con Undo (z) ──────────────────────────────────────
  izquierdo(c){
    if(c && c.celda){
      const bx = c.celda[0], by = c.celda[1], bz = c.celda[2];
      const before = mc.grid[mcIdx(bx, by, bz)];
      if(before){
        mcSetBlock(bx, by, bz, 0);
        mcPushHist({ t: 'b', x: bx, y: by, z: bz, before, after: 0 });
        mcRemeshAround(bx, bz);
        mcScheduleSave();
      }
    } else {
      mcBreak();
    }
  },

  // ── BOTÓN DERECHO: Poner bajo los pies (sin preview ni modo pegar) ──────────────────────────────
  async derecho(c){
    const cx = Math.floor(mc.pos[0]);
    const cy = Math.floor(mc.pos[1]);
    const cz = Math.floor(mc.pos[2]);
    const targetY = cy - 1;

    // Si el modo K está activo, colocamos el conjunto de bloques del recorte K bajo los pies
    if (mc._sueloUsaK) {
      const lista = typeof mcRecortesCarga === 'function' ? mcRecortesCarga() : (mc.recortes || []);
      const r = lista[mc.recorteSel | 0];
      if (!r || !r.cells || !r.cells.length) {
        toast('La ranura K no tiene ningún recorte guardado');
        return;
      }

      const cells = r.cells;
      const dim = typeof mcRecorteDim === 'function' ? mcRecorteDim(r) : { w: 1, d: 1, h: 1 };
      const ox = Math.floor(dim.w / 2);
      const oz = Math.floor(dim.d / 2);

      // Resolver claves de materiales
      const keyId = {}, colorId = {};
      for(const cel of cells){
        const v = cel.c;
        if(typeof v === 'string' && v.slice(0,4) === 'tex:'){
          const key = v.slice(4);
          if(!(key in keyId)) keyId[key] = await mcAddBlock(key);
        } else {
          const hx = String(v);
          if(!(hx in colorId)) colorId[hx] = typeof mcNearestMaterial === 'function' ? mcNearestMaterial(hx) : mcResolveMat('log');
        }
      }

      const edits = [];
      for(const cel of cells){
        let id;
        if(typeof cel.c === 'string' && cel.c.slice(0,4) === 'tex:') id = keyId[cel.c.slice(4)];
        else id = colorId[String(cel.c)];
        if(!id) continue;

        // cel.dx = X, cel.dy = Z (profundidad), cel.dz = Y (altura)
        const wx = cx + (cel.dx - ox);
        const wy = targetY + (cel.dz || 0);
        const wz = cz + (cel.dy - oz);

        if(!mcInside(wx, wy, wz)) continue;
        const before = mc.grid[mcIdx(wx, wy, wz)];
        if(before === id) continue;

        mcSetBlock(wx, wy, wz, id);
        edits.push({ x, y: wy, z: wz, before, after: id });
      }

      if(!edits.length) return;

      mcPushHist({ t: 'bb', edits });
      mcRemeshEdiciones(edits);
      mcScheduleSave();
      mcUnstick();
      toast('Recorte «' + r.nombre + '» colocado bajo los pies');
      return;
    }

    // Si no está en modo K: modo normal de ranura activa 1-9 (baldosa 3x3 bajo los pies)
    const matId = (mc.hotbar && mc.hotbar[mc.sel]) || mcResolveMat('log');
    if (!matId) return;

    const edits = [];
    for (let x = cx - 1; x <= cx + 1; x++){
      for (let z = cz - 1; z <= cz + 1; z++){
        if (!mcInside(x, targetY, z)) continue;
        const idx = mcIdx(x, targetY, z);
        const before = mc.grid[idx];
        if (before === matId) continue;

        mcSetBlock(x, targetY, z, matId);
        edits.push({ x, y: targetY, z, before, after: matId });
      }
    }

    if (!edits.length) return;

    mcPushHist({ t: 'bb', edits });
    mcRemeshEdiciones(edits);
    mcScheduleSave();
    mcUnstick();
  }
});

game.playerTool = 'suelo_flotante_recortes';
toast('🗡️ suelo_flotante (con K) lista · Pulsa 1-9 o K para elegir qué colocar bajo los pies');
